instruction:
Finish the two front-end tools that already exist in `/workspace`:
the lexical analyzer under `LexicalAnalyzer/` and the LL(1) parser under
`Parser/`. This is not a greenfield compiler project; the code is present, but
the core logic for tokenization and table-driven parsing is incomplete.

`LexicalAnalyzer/LexicalAnalysis.cpp`
Complete the preprocessing and tokenization pipeline: comment removal,
whitespace normalization, identifier and integer recognition, token
classification, illegal-token location reporting, and the final token/error
output written to `processed.txt`.

`Parser/SyntacticParser.cpp`
Complete the grammar-loading and LL(1) workflow: production parsing,
FIRST/FOLLOW computation, LL(1) table construction, parse-trace output, and
the table-driven analysis loop.

The tests execute the compiled binaries and depend on these exact entry points:

```cpp
bool preProcess(const string fileName, const string newFileName);
bool mainProcess(const string fileName, const string fileNameProcessed);
bool IsIdentifier(const string word);
bool IsNum(const string word);
int wtMatch(const string word);
string findError(const string fileName, const string value);
string load_file(string file_name);
void split_into_rules(const string text, vector<rule>& rules, set<char>& non_terminal, set<char>& terminal, set<string>& right_parts);
ostream& operator<<(ostream& out, rule rule);
void check_rules(const vector<rule> rules);
template <class T> void check_set(set<T> set_, string tip);
ostream& operator<<(ostream& out, F_set f_set);
F_set findFirst(const string ss, vector<rule> rules);
vector<F_set> checkFirst(set<string> right_parts, vector<rule> rules);
F_set findFollow(const char non_terminal, vector<rule> rules);
vector<F_set> checkFollow(set<char> non_terminal, vector<rule> rules);
LL_1_table LL_1(set<char>& terminal, set<char>& non_terminal, vector<rule> rules);
ostream& operator<<(ostream& out, LL_1_table table);
void print_state(stack<char> analysis_s, stack<char> input_s, rule& rule_temp);
void syntacticAnalysis(LL_1_table table);
```
